#[test]
fn vector_primitive_metrics_and_update_commands_match_reference() {
    for case in fixture()["vector3DTilePrimitive"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let batch_ids = u16s(&case["batchIds"]);
        let index_counts = u32s(&case["indexCounts"]);
        let index_offsets = u32s(&case["indexOffsets"]);
        let indices_len = *index_offsets.last().unwrap_or(&0) as usize + *index_counts.last().unwrap_or(&0) as usize;
        let batched: Vec<Vector3DTileBatch> = case["initial"]
            .as_array()
            .unwrap()
            .iter()
            .map(|batch| Vector3DTileBatch {
                offset: batch["offset"].as_u64().unwrap() as usize,
                count: batch["count"].as_u64().unwrap() as usize,
                color: Color::from_rgba(batch["rgba"].as_u64().unwrap() as u32),
                batch_ids: batch["batchIds"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect(),
            })
            .collect();
        let mut primitive = Vector3DTilePrimitive::<GlStub>::new(Vector3DTilePrimitiveOptions {
            positions: vec![0.0; batch_ids.len() * 3],
            vertex_batch_ids: batch_ids.clone(),
            indices: TypedArray::Uint16(vec![0; indices_len]),
            index_counts: index_counts.clone(),
            index_offsets: index_offsets.clone(),
            batched_indices: batched,
            batch_ids,
            bounding_volume: BoundingSphere::new(Cartesian3::ZERO, 1.0),
            ..Default::default()
        });
        assert_eq!(primitive.triangles_length(), case["trianglesLength"].as_f64().unwrap(), "{name}: triangles");
        assert_eq!(
            primitive.geometry_byte_length(),
            case["geometryByteLength"].as_u64().unwrap() as usize,
            "{name}: bytes"
        );

        for (step_index, step) in case["steps"].as_array().unwrap().iter().enumerate() {
            let batch_id = step["batchId"].as_u64().unwrap() as u16;
            let color_values = f64s(&step["color"]);
            primitive.update_commands(
                batch_id,
                Color::new(color_values[0], color_values[1], color_values[2], color_values[3]),
            );
            let actual: Vec<(usize, usize, u32, Vec<u32>)> = primitive
                .batched_indices
                .iter()
                .map(|b| (b.offset, b.count, b.color.to_rgba(), b.batch_ids.clone()))
                .collect();
            let expected: Vec<(usize, usize, u32, Vec<u32>)> = step["batches"]
                .as_array()
                .unwrap()
                .iter()
                .map(|b| {
                    (
                        b["offset"].as_u64().unwrap() as usize,
                        b["count"].as_u64().unwrap() as usize,
                        b["rgba"].as_u64().unwrap() as u32,
                        b["batchIds"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect(),
                    )
                })
                .collect();
            assert_eq!(actual, expected, "{name}: step {step_index}");
        }
    }
}

// =============================================================================
// Vector3DTileContent payload construction
// =============================================================================

fn zip_zag(values: &[u16]) -> Vec<u16> {
    let mut out = Vec::with_capacity(values.len());
    let mut previous = 0i32;
    for &value in values {
        let value = i32::from(value);
        let delta = value - previous;
        previous = value;
        out.push((((delta << 1) ^ (delta >> 31)) & 0xffff) as u16);
    }
    out
}

fn encode(us: &[u16], vs: &[u16], hs: Option<&[u16]>) -> Vec<u16> {
    let mut out = zip_zag(us);
    out.extend(zip_zag(vs));
    if let Some(hs) = hs {
        out.extend(zip_zag(hs));
    }
    out
}

#[allow(clippy::too_many_arguments)]
fn build_vector_tile(
    version: u32,
    byte_length_override: Option<u32>,
    feature_json: &[u8],
    feature_binary: &[u8],
    batch_json: &[u8],
    batch_binary: &[u8],
    polygon_indices: &[u32],
    polygon_positions: &[u16],
    polyline_positions: &[u16],
    points_positions: &[u16],
) -> Arc<Vec<u8>> {
    let mut padded_features = feature_json.to_vec();
    while !padded_features.len().is_multiple_of(8) {
        padded_features.push(b' ');
    }
    let header = 4 + 4 + 4 + 8 * 4;
    let mut offset = header + padded_features.len() + feature_binary.len() + batch_json.len() + batch_binary.len();
    offset += (4 - (offset % 4)) % 4;
    let total = offset
        + polygon_indices.len() * 4
        + polygon_positions.len() * 2
        + polyline_positions.len() * 2
        + points_positions.len() * 2;
    let mut bytes = vec![0u8; total];
    bytes[0..4].copy_from_slice(b"vctr");
    let put_u32 = |bytes: &mut Vec<u8>, at: usize, value: u32| {
        bytes[at..at + 4].copy_from_slice(&value.to_le_bytes());
    };
    put_u32(&mut bytes, 4, version);
    put_u32(&mut bytes, 8, byte_length_override.unwrap_or(total as u32));
    put_u32(&mut bytes, 12, padded_features.len() as u32);
    put_u32(&mut bytes, 16, feature_binary.len() as u32);
    put_u32(&mut bytes, 20, batch_json.len() as u32);
    put_u32(&mut bytes, 24, batch_binary.len() as u32);
    put_u32(&mut bytes, 28, (polygon_indices.len() * 4) as u32);
    put_u32(&mut bytes, 32, (polygon_positions.len() * 2) as u32);
    put_u32(&mut bytes, 36, (polyline_positions.len() * 2) as u32);
    put_u32(&mut bytes, 40, (points_positions.len() * 2) as u32);
    let mut cursor = header;
    bytes[cursor..cursor + padded_features.len()].copy_from_slice(&padded_features);
    cursor += padded_features.len();
    bytes[cursor..cursor + feature_binary.len()].copy_from_slice(feature_binary);
    cursor += feature_binary.len();
    bytes[cursor..cursor + batch_json.len()].copy_from_slice(batch_json);
    cursor += batch_json.len();
    bytes[cursor..cursor + batch_binary.len()].copy_from_slice(batch_binary);
    cursor += batch_binary.len();
    cursor += (4 - (cursor % 4)) % 4;
    for (i, value) in polygon_indices.iter().enumerate() {
        put_u32(&mut bytes, cursor + i * 4, *value);
    }
    cursor += polygon_indices.len() * 4;
    for (i, value) in polygon_positions.iter().enumerate() {
        bytes[cursor + i * 2..cursor + i * 2 + 2].copy_from_slice(&value.to_le_bytes());
    }
    cursor += polygon_positions.len() * 2;
    for (i, value) in polyline_positions.iter().enumerate() {
        bytes[cursor + i * 2..cursor + i * 2 + 2].copy_from_slice(&value.to_le_bytes());
    }
    cursor += polyline_positions.len() * 2;
    for (i, value) in points_positions.iter().enumerate() {
        bytes[cursor + i * 2..cursor + i * 2 + 2].copy_from_slice(&value.to_le_bytes());
    }
    Arc::new(bytes)
}

fn standard_vector_tile() -> Arc<Vec<u8>> {
    let feature_json = br#"{"POLYGONS_LENGTH":2,"POLYGON_COUNTS":[4,3],"POLYGON_INDEX_COUNTS":[6,3],"POLYLINES_LENGTH":2,"POLYLINE_COUNTS":[3,2],"POINTS_LENGTH":2,"REGION":[-1.0,-1.0,1.0,1.0,10,100]}"#;
    let batch_json = br#"{"name":["a","b","c","d","e","f"]}"#;
    let polyline_positions =
        encode(&[1000, 1200, 1400, 1600, 1800], &[2000, 2200, 2400, 2600, 2800], Some(&[3000, 3200, 3400, 3600, 3800]));
    let points_positions = encode(&[500, 700], &[900, 1100], Some(&[1300, 1500]));
    build_vector_tile(
        1,
        None,
        feature_json,
        &[],
        batch_json,
        &[],
        &[0, 1, 2, 0, 2, 1, 0, 1, 2],
        &[100, 200, 300, 400, 500, 600, 700, 800, 900, 1000, 1100, 1200, 1300, 1400],
        &polyline_positions,
        &points_positions,
    )
}

fn content_options(classification_type: Option<cesium_rs::scene::ClassificationType>) -> Vector3DTileContentOptions {
    Vector3DTileContentOptions {
        url: "https://example.test/tile.vctr".into(),
        model_matrix: Matrix4::IDENTITY,
        bounding_volume: BoundingSphere::new(Cartesian3::ZERO, 1000.0),
        classification_type,
        height_reference: HeightReference::None,
        vector_keep_decoded_positions: false,
        debug_wireframe: false,
        ellipsoid: Ellipsoid::WGS84,
        examine_vector_lines: None,
    }
}

#[test]
fn vector_tile_content_matches_reference_parse() {
    for case in fixture()["vector3DTileContent"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let classification = if name == "clamped" { Some(cesium_rs::scene::ClassificationType::Terrain) } else { None };
        let content =
            Vector3DTileContent::<GlStub>::from_bytes(content_options(classification), standard_vector_tile(), 0)
                .unwrap_or_else(|e| panic!("{name}: {}", e.message));
        assert_eq!(content.features_length() as u64, case["featuresLength"].as_u64().unwrap(), "{name}: features");
        assert_eq!(content.points_length() as u64, case["pointsLength"].as_u64().unwrap(), "{name}: points");
        assert_eq!(content.triangles_length(), case["trianglesLength"].as_f64().unwrap(), "{name}: triangles");
        assert_eq!(
            content.geometry_byte_length() as u64,
            case["geometryByteLength"].as_u64().unwrap(),
            "{name}: geometry"
        );
        assert_eq!(
            content.textures_byte_length() as u64,
            case["texturesByteLength"].as_u64().unwrap(),
            "{name}: textures"
        );
        assert_eq!(
            content.batch_table_byte_length() as u64,
            case["batchTableByteLength"].as_u64().unwrap(),
            "{name}: batch table"
        );
        assert_eq!(content.ready(), case["ready"].as_bool().unwrap(), "{name}: ready");
        assert_eq!(content.url(), case["url"].as_str().unwrap(), "{name}: url");
        assert_eq!(content.inner_contents().is_none(), case["innerContents"].is_null());
        assert_eq!(content.has_property(0, "name"), case["hasProperty"].as_bool().unwrap(), "{name}: hasProperty");

        let polygons = case["polygons"].as_object().unwrap();
        let polygon = content.polygons().unwrap();
        assert_eq!(polygon.batch_ids(), u16s(&polygons["batchIds"]).as_slice(), "{name}: polygon ids");
        assert_eq!(polygon.counts(), u32s(&polygons["counts"]).as_slice(), "{name}: polygon counts");
        assert_eq!(polygon.positions_len(), polygons["positionsLength"].as_u64().unwrap() as usize);
        assert_eq!(polygon.minimum_height(), polygons["minHeight"].as_f64().unwrap());
        assert_eq!(polygon.maximum_height(), polygons["maxHeight"].as_f64().unwrap());

        let polylines = case["polylines"].as_object().unwrap();
        let expected_center = f64s(&polylines["center"]);
        if name == "clamped" {
            let polyline = content.clamped_polylines().unwrap();
            assert_eq!(polyline.batch_ids(), u16s(&polylines["batchIds"]).as_slice(), "{name}: polyline ids");
            assert_eq!(polyline.counts(), u32s(&polylines["counts"]).as_slice(), "{name}: polyline counts");
            assert_eq!(polyline.positions_len(), polylines["positionsLength"].as_u64().unwrap() as usize);
            assert_eq!(polyline.widths(), u16s(&polylines["widths"]).as_slice(), "{name}: widths");
            assert_eq!(polyline.minimum_height(), polylines["minHeight"].as_f64().unwrap());
            assert_eq!(polyline.maximum_height(), polylines["maxHeight"].as_f64().unwrap());
            assert!((polyline.center().x - expected_center[0]).abs() < 1e-3);
            assert!((polyline.center().y - expected_center[1]).abs() < 1e-3);
            assert!((polyline.center().z - expected_center[2]).abs() < 1e-3);
        } else {
            let polyline = content.polylines().unwrap();
            assert_eq!(polyline.batch_ids(), u16s(&polylines["batchIds"]).as_slice(), "{name}: polyline ids");
            assert_eq!(polyline.counts(), u32s(&polylines["counts"]).as_slice(), "{name}: polyline counts");
            assert_eq!(polyline.positions_len(), polylines["positionsLength"].as_u64().unwrap() as usize);
            assert_eq!(polyline.widths(), u16s(&polylines["widths"]).as_slice(), "{name}: widths");
            assert_eq!(polyline.minimum_height(), polylines["minHeight"].as_f64().unwrap());
            assert_eq!(polyline.maximum_height(), polylines["maxHeight"].as_f64().unwrap());
            assert!((polyline.center().x - expected_center[0]).abs() < 1e-3);
            assert!((polyline.center().y - expected_center[1]).abs() < 1e-3);
            assert!((polyline.center().z - expected_center[2]).abs() < 1e-3);
        }

        let points = case["points"].as_object().unwrap();
        let points_content = content.points().unwrap();
        assert_eq!(points_content.batch_ids(), u16s(&points["batchIds"]).as_slice(), "{name}: point ids");
        assert_eq!(points_content.positions_len(), points["positionsLength"].as_u64().unwrap() as usize);
    }
}

#[test]
fn vector_tile_content_errors_match_reference() {
    let fixture_value = fixture();
    let cases = fixture_value["vector3DTileContentErrors"].as_array().unwrap();
    for case in cases {
        let name = case["name"].as_str().unwrap();
        let bytes = match name {
            "bad-version" => build_vector_tile(2, None, br#"{"POLYGONS_LENGTH":0}"#, &[], &[], &[], &[], &[], &[], &[]),
            "zero-byte-length" => {
                build_vector_tile(1, Some(0), br#"{"POLYGONS_LENGTH":0}"#, &[], &[], &[], &[], &[], &[], &[])
            }
            "empty-feature-json" => build_vector_tile(1, None, &[], &[], &[], &[], &[], &[], &[], &[]),
            "missing-region" => build_vector_tile(
                1,
                None,
                br#"{"POLYGONS_LENGTH":1,"POLYGON_COUNTS":[3],"POLYGON_INDEX_COUNTS":[3]}"#,
                &[],
                &[],
                &[],
                &[0, 1, 2],
                &[0, 1, 2, 3, 4, 5],
                &[],
                &[],
            ),
            "missing-polygon-counts" => build_vector_tile(
                1,
                None,
                br#"{"POLYGONS_LENGTH":1,"POLYGON_INDEX_COUNTS":[3],"REGION":[-1,-1,1,1,0,1]}"#,
                &[],
                &[],
                &[],
                &[0, 1, 2],
                &[],
                &[],
                &[],
            ),
            "missing-index-counts" => build_vector_tile(
                1,
                None,
                br#"{"POLYGONS_LENGTH":1,"POLYGON_COUNTS":[3],"REGION":[-1,-1,1,1,0,1]}"#,
                &[],
                &[],
                &[],
                &[0, 1, 2],
                &[0, 1, 2, 3, 4, 5],
                &[],
                &[],
            ),
            "missing-polyline-counts" => build_vector_tile(
                1,
                None,
                br#"{"POLYLINES_LENGTH":1,"REGION":[-1,-1,1,1,0,1]}"#,
                &[],
                &[],
                &[],
                &[],
                &[],
                &encode(&[1, 2], &[3, 4], Some(&[5, 6])),
                &[],
            ),
            _ => unreachable!("{name}"),
        };
        let result = Vector3DTileContent::<GlStub>::from_bytes(content_options(None), bytes, 0);
        if let Some(error) = case["error"].as_str() {
            let actual = result.err().unwrap_or_else(|| panic!("{name}: expected {error}"));
            assert_eq!(actual.message, error, "{name}");
        } else {
            let content = result.unwrap_or_else(|e| panic!("{name}: {}", e.message));
            assert_eq!(content.ready(), case["ready"].as_bool().unwrap(), "{name}: ready");
            assert_eq!(content.features_length() as u64, case["featuresLength"].as_u64().unwrap(), "{name}: features");
        }
    }
}

