#[test]
fn gaussian_half_floats_match_pinned_conversion() {
    for case in fixture()["gaussianSplat3DTileContent"]["halfFloats"].as_array().unwrap() {
        let value = match case["value"].as_str() {
            Some("NaN") => f32::NAN,
            Some("Infinity") => f32::INFINITY,
            Some("-Infinity") => f32::NEG_INFINITY,
            Some("-0") => -0.0,
            Some(text) => text.parse::<f32>().unwrap(),
            None => case["value"].as_f64().unwrap() as f32,
        };
        assert_eq!(float32_to_float16(value), case["bits"].as_u64().unwrap() as u16, "value {value}");
    }
}

fn sh_attributes(count: usize) -> Vec<GaussianSplatAttribute> {
    (0..count)
        .map(|i| {
            GaussianSplatAttribute::new(
                format!("_SH_DEGREE_1_COEF_{i}"),
                vec![i as f32 + 0.25, i as f32 + 0.5, i as f32 + 0.75, 0.0, 0.0, 0.0],
                2,
            )
        })
        .collect()
}

#[test]
fn gaussian_degree_and_names_match_pinned_helpers() {
    for case in fixture()["gaussianSplat3DTileContent"]["degreeCases"].as_array().unwrap() {
        let count = case["count"].as_u64().unwrap() as usize;
        assert_eq!(
            degree_and_coef_from_attributes(&sh_attributes(count)),
            (case["l"].as_u64().unwrap() as u32, case["n"].as_u64().unwrap() as usize),
            "count {count}"
        );
    }
    for case in fixture()["gaussianSplat3DTileContent"]["degreeNames"].as_array().unwrap() {
        let name = case["name"].as_str().unwrap();
        let (l, n) = extract_sh_degree_and_coef(name);
        match (case["l"].as_f64(), case["n"].as_f64()) {
            (Some(expected_l), Some(expected_n)) => {
                assert_eq!(l, expected_l, "{name}: l");
                assert_eq!(n, expected_n, "{name}: n");
            }
            _ => {
                assert!(l.is_nan() && n.is_nan(), "{name}: expected NaN, got {l}/{n}");
            }
        }
    }
}

#[test]
fn gaussian_spherical_harmonics_packing_matches_reference() {
    for case in fixture()["gaussianSplat3DTileContent"]["packing"].as_array().unwrap() {
        let degree = case["degree"].as_u64().unwrap() as u32;
        let points = case["points"].as_u64().unwrap() as usize;
        let coefficient_count = match degree {
            1 => 9,
            2 => 24,
            3 => 45,
            _ => 0,
        };
        let seed = match degree {
            1 => 3usize,
            2 => 5,
            _ => 11,
        };
        let mut attributes = Vec::new();
        for n in 0..coefficient_count {
            let mut values = vec![0f32; points * 3];
            for (i, value) in values.iter_mut().enumerate() {
                *value = (((seed + i * 13 + n * 7) % 211) as f64 / 17.0 - 6.0) as f32;
            }
            attributes.push(GaussianSplatAttribute::new(format!("_SH_DEGREE_{degree}_COEF_{n}"), values, points));
        }
        let actual = pack_spherical_harmonics_data(points, degree, coefficient_count, &attributes);
        let expected: Vec<u32> =
            case["packed"].as_array().unwrap().iter().map(|v| v.as_u64().unwrap() as u32).collect();
        assert_eq!(actual, expected, "degree {degree}");
    }
}

